    """ Split input list into 2 lists, one contains all strings that are a substring of given pattern and
    the second list contains all the others.
    >>> split_and_drop(['abc', 'bacd', 'cde', 'array'], 'abc')
    ([['abc'], ['array']], [['bacd', 'cde']])
    """
    substring_strings = []
    all_strings = []
    for string in strings:
        if pattern in string:
            substring_strings.append(string)
        else:
            all_strings.append(string)
    return substring_strings, all_strings


def unique_chars(strings: List[str]) -> int:
    """ Count unique characters in the input list.
    >>> unique_chars(['abc', 'bacd', 'cde', 'array'])
    8
    """
    counts = {}
    for string in strings:
        for char in string:
            if char not in counts:
                counts[char] = 1
            else:
                counts[char] += 1
    return len(counts)

