def parse_nested_parens_2(paren_string: str) -> List[int]:
    """ In contrast to above solution, this one uses more memory but solves the problem in O(n) time.
    Output to the function is the same as in the previous example.
    >>> parse_nested_parens_2('(()()) ((())) () ((())()())')
    [2, 3, 1, 3]
    """
    stack = []
    levels = []

    for i in range(len(paren_string)):
        # Check if we found a pair of parentheses. Push the current length on stack if yes.
        if paren_string[i] == '(':
            if len(stack) == 0:
                levels.append(i + 1)
            else:
                levels.append(stack.pop())
        elif paren_string[i] == ')':
            # If stack is empty, the previous pair of parentheses was found at the end of string.
            # Append the level to our list.
            if len(stack) == 0:
                levels.append(i + 1)
            else:
                levels.append(stack.pop())

    return levels


